<?php field('position_seconds','Resume position (seconds)',$progress['position_seconds'],'number',['min'=>'0','max'=>'604800','data-learning-position'=>'1']);field('note','Private notes',$progress['note'],'textarea',['maxlength'=>'10000']);check_field('completed','Mark as completed',(bool)$progress['completed']);button('Save progress','','check'); ?><output class="platform-output" data-learning-status role="status"></output></form><p class="hint"><?= t('Progress is self-reported, not certified viewing time. Save before closing the page. Player position is copied when playback pauses.') ?></p></section><?php else: ?><a class="btn secondary" href="<?= e(url('login')) ?>"><?= t('Sign in to save learning progress.') ?></a><?php endif ?>
</div><aside class="learning-outline panel commerce-panel"><h2><?= t('Lesson outline') ?></h2><ol class="lesson-outline"><?php foreach($course['lessons'] as $l): ?><li><a <?= $course['allowed']||$l['preview']?'href="'.e(url('learn',['id'=>$l['id']])).'"':'aria-disabled="true"' ?> class="<?= (int)$l['id']===(int)$lesson['id']?'active':'' ?>" <?= (int)$l['id']===(int)$lesson['id']?'aria-current="step"':'' ?>><strong><?= e($l['title']) ?></strong><?= icon($l['preview']||$course['allowed']?'arrow':'lock') ?></a></li><?php endforeach ?></ol></aside></section>
